import zipfile,xml.etree.ElementTree as E,re,posixpath,sys
def sheets(p):
 z=zipfile.ZipFile(p); parse=lambda n:E.fromstring(z.read(n))
 strings=[''.join(t.text or '' for t in x.findall('.//{*}t')) for x in parse('xl/sharedStrings.xml')] if 'xl/sharedStrings.xml' in z.namelist() else []
 rel={x.get('Id'):x.get('Target') for x in parse('xl/_rels/workbook.xml.rels')}
 for s in parse('xl/workbook.xml').findall('.//{*}sheet'):
  target=rel[next(v for k,v in s.attrib.items() if k.endswith('}id'))]
  rows={}
  for row in parse(target.lstrip('/') if target.startswith('/') else posixpath.join('xl',target)).findall('.//{*}row'):
   d={}
   for c in row:
    v=c.findtext('{*}v'); t=c.get('t')
    if t=='s':v=strings[int(v)]
